values (
  'cp-practice-binary-tree-96', 'dt-practice-binary-tree', null,
  $px$Inorder Traversal$px$, $px$inorder-traversal$px$, $px$Easy$px$,
  $px$Given a binary tree, print its nodes in Left -> Root -> Right (inorder) order.

The tree is given in level order: `M` tokens, each an integer or `null`. The first token is the root; `null` marks a missing child. Children of a `null` are not listed.

**Input Format**

The first line contains an integer `M`, the number of level-order tokens.
The second line contains `M` space-separated tokens (integers or `null`). It is blank when `M` is 0.

**Output Format**

Print the inorder traversal values separated by single spaces, or an empty line for an empty tree.$px$,
  $px$[{"input":"4\n1 null 2 3","output":"1 3 2","explanation":"Visit the left subtree, then the root, then the right subtree."}]$px$::jsonb,
  $px$["0 <= number of nodes <= 5000","-1000000000 <= node value <= 1000000000"]$px$::jsonb,
  $px${"java":"import java.util.*;\nimport java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        // TODO: read the input, compute the answer, and print it\n    }\n}\n","python":"import sys\n\ndata = sys.stdin.read()\n# TODO: parse the input above and print the answer\n","c":"#include <stdio.h>\n\nint main(void) {\n    // TODO: read input with scanf / fgets, compute, print with printf\n    return 0;\n}\n","cpp":"#include <iostream>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    // TODO: read the input, compute the answer, and print it\n    return 0;\n}\n","javascript":"const data = require('fs').readFileSync(0, 'utf8');\n// TODO: parse the input above and print the answer\n"}$px$::jsonb,
  $px${"java":"import java.util.*;\nimport java.io.*;\npublic class Main {\n    static int[] L, R, V;\n    static StringBuilder sb = new StringBuilder();\n    static boolean first = true;\n    static void go(int x) {\n        if (x == -1) return;\n        go(L[x]);\n        if (!first) sb.append(' ');\n        sb.append(V[x]); first = false;\n        go(R[x]);\n    }\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        int m = Integer.parseInt(br.readLine().trim());\n        String line = br.readLine();\n        String[] toks = (m > 0 && line != null) ? line.trim().split(\"\\\\s+\") : new String[0];\n        int[] Lt = new int[Math.max(1, m)], Rt = new int[Math.max(1, m)], Vt = new int[Math.max(1, m)];\n        int cnt = 0;\n        if (toks.length > 0) {\n            Vt[0] = Integer.parseInt(toks[0]); Lt[0] = -1; Rt[0] = -1; cnt = 1;\n            int[] q = new int[m + 1]; int qh = 0, qt = 0; q[qt++] = 0; int i = 1;\n            while (qh < qt && i < toks.length) {\n                int curr = q[qh++];\n                if (i < toks.length && !toks[i].equals(\"null\")) { Vt[cnt] = Integer.parseInt(toks[i]); Lt[cnt] = -1; Rt[cnt] = -1; Lt[curr] = cnt; q[qt++] = cnt; cnt++; }\n                i++;\n                if (i < toks.length && !toks[i].equals(\"null\")) { Vt[cnt] = Integer.parseInt(toks[i]); Lt[cnt] = -1; Rt[cnt] = -1; Rt[curr] = cnt; q[qt++] = cnt; cnt++; }\n                i++;\n            }\n        }\n        L = Lt; R = Rt; V = Vt;\n        if (cnt > 0) go(0);\n        System.out.println(sb.toString());\n    }\n}\n","python":"import sys\nsys.setrecursionlimit(20000)\nlines = sys.stdin.read().split('\\n')\nm = int(lines[0])\ntoks = lines[1].split() if m > 0 else []\nval, L, R = [], [], []\nif toks:\n    val.append(int(toks[0])); L.append(-1); R.append(-1)\n    q = [0]; qh = 0; i = 1\n    while qh < len(q) and i < len(toks):\n        cur = q[qh]; qh += 1\n        if i < len(toks) and toks[i] != 'null':\n            val.append(int(toks[i])); L.append(-1); R.append(-1); L[cur] = len(val) - 1; q.append(len(val) - 1)\n        i += 1\n        if i < len(toks) and toks[i] != 'null':\n            val.append(int(toks[i])); L.append(-1); R.append(-1); R[cur] = len(val) - 1; q.append(len(val) - 1)\n        i += 1\nout = []\ndef go(x):\n    if x == -1:\n        return\n    go(L[x]); out.append(str(val[x])); go(R[x])\nif val:\n    go(0)\nprint(' '.join(out))\n","c":"#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\nint *L, *R;\nlong long *V;\nchar sb[200000];\nint pos = 0, firstOut = 1;\nvoid go(int x) {\n    if (x == -1) return;\n    go(L[x]);\n    if (!firstOut) sb[pos++] = ' ';\n    pos += sprintf(sb + pos, \"%lld\", V[x]);\n    firstOut = 0;\n    go(R[x]);\n}\nint main(void) {\n    int m;\n    if (scanf(\"%d\", &m) != 1) return 0;\n    char **toks = malloc(sizeof(char*) * (m > 0 ? m : 1));\n    int t = 0;\n    for (int i = 0; i < m; i++) { toks[t] = malloc(16); scanf(\"%15s\", toks[t]); t++; }\n    L = malloc(sizeof(int) * (m > 0 ? m : 1));\n    R = malloc(sizeof(int) * (m > 0 ? m : 1));\n    V = malloc(sizeof(long long) * (m > 0 ? m : 1));\n    int cnt = 0;\n    if (t > 0) {\n        V[0] = atoll(toks[0]); L[0] = -1; R[0] = -1; cnt = 1;\n        int *q = malloc(sizeof(int) * (m + 1)); int qh = 0, qt = 0; q[qt++] = 0; int i = 1;\n        while (qh < qt && i < t) {\n            int cur = q[qh++];\n            if (i < t && strcmp(toks[i], \"null\") != 0) { V[cnt] = atoll(toks[i]); L[cnt] = -1; R[cnt] = -1; L[cur] = cnt; q[qt++] = cnt; cnt++; }\n            i++;\n            if (i < t && strcmp(toks[i], \"null\") != 0) { V[cnt] = atoll(toks[i]); L[cnt] = -1; R[cnt] = -1; R[cur] = cnt; q[qt++] = cnt; cnt++; }\n            i++;\n        }\n        free(q);\n    }\n    if (cnt > 0) go(0);\n    sb[pos] = 0;\n    printf(\"%s\\n\", sb);\n    return 0;\n}\n","cpp":"#include <iostream>\n#include <vector>\n#include <string>\n#include <sstream>\nusing namespace std;\nvector<int> L, R;\nvector<long long> V;\nvector<long long> out;\nvoid go(int x) {\n    if (x == -1) return;\n    go(L[x]); out.push_back(V[x]); go(R[x]);\n}\nint main() {\n    ios::sync_with_stdio(false); cin.tie(nullptr);\n    int m; cin >> m;\n    cin.ignore();\n    string line;\n    getline(cin, line);\n    vector<string> toks;\n    { istringstream iss(line); string tk; while (iss >> tk) toks.push_back(tk); }\n    int cnt = 0;\n    if (!toks.empty()) {\n        V.push_back(stoll(toks[0])); L.push_back(-1); R.push_back(-1); cnt = 1;\n        vector<int> q{0}; size_t qh = 0, i = 1;\n        while (qh < q.size() && i < toks.size()) {\n            int cur = q[qh++];\n            if (i < toks.size() && toks[i] != \"null\") { V.push_back(stoll(toks[i])); L.push_back(-1); R.push_back(-1); L[cur] = cnt; q.push_back(cnt); cnt++; }\n            i++;\n            if (i < toks.size() && toks[i] != \"null\") { V.push_back(stoll(toks[i])); L.push_back(-1); R.push_back(-1); R[cur] = cnt; q.push_back(cnt); cnt++; }\n            i++;\n        }\n    }\n    if (cnt > 0) go(0);\n    for (size_t k = 0; k < out.size(); k++) { if (k) cout << ' '; cout << out[k]; }\n    cout << \"\\n\";\n    return 0;\n}\n","javascript":"const lines = require('fs').readFileSync(0, 'utf8').split('\\n');\nconst m = Number(lines[0]);\nconst toks = m > 0 ? lines[1].trim().split(/\\s+/) : [];\nconst V = [], L = [], R = [];\nif (toks.length) {\n    V.push(Number(toks[0])); L.push(-1); R.push(-1);\n    const q = [0]; let qh = 0, i = 1;\n    while (qh < q.length && i < toks.length) {\n        const cur = q[qh++];\n        if (i < toks.length && toks[i] !== 'null') { V.push(Number(toks[i])); L.push(-1); R.push(-1); L[cur] = V.length - 1; q.push(V.length - 1); }\n        i++;\n        if (i < toks.length && toks[i] !== 'null') { V.push(Number(toks[i])); L.push(-1); R.push(-1); R[cur] = V.length - 1; q.push(V.length - 1); }\n        i++;\n    }\n}\nconst out = [];\nfunction go(x) { if (x === -1) return; go(L[x]); out.push(V[x]); go(R[x]); }\nif (V.length) go(0);\nconsole.log(out.join(' '));\n"}$px$::jsonb,
