  $px$Count Leaf Nodes$px$, $px$count-leaf-nodes$px$, $px$Easy$px$,
  $px$Count the number of nodes in a binary tree that have no children.

**Input Format**

The first line contains an integer `M`, the number of level-order tokens.
The second line contains `M` space-separated tokens (integers or `null`). It is blank when `M` is 0.

**Output Format**

Print the number of leaf nodes.$px$,
  $px$[{"input":"5\n1 2 3 4 5","output":"3","explanation":"Nodes 4, 5 and 3 are leaves."}]$px$::jsonb,
  $px$["0 <= number of nodes <= 5000","-1000000000 <= node value <= 1000000000"]$px$::jsonb,
  $px${"java":"import java.util.*;\nimport java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        // TODO: read the input, compute the answer, and print it\n    }\n}\n","python":"import sys\n\ndata = sys.stdin.read()\n# TODO: parse the input above and print the answer\n","c":"#include <stdio.h>\n\nint main(void) {\n    // TODO: read input with scanf / fgets, compute, print with printf\n    return 0;\n}\n","cpp":"#include <iostream>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    // TODO: read the input, compute the answer, and print it\n    return 0;\n}\n","javascript":"const data = require('fs').readFileSync(0, 'utf8');\n// TODO: parse the input above and print the answer\n"}$px$::jsonb,
  $px${"java":"import java.util.*;\nimport java.io.*;\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        int m = Integer.parseInt(br.readLine().trim());\n        String line = br.readLine();\n        String[] toks = (m > 0 && line != null) ? line.trim().split(\"\\\\s+\") : new String[0];\n        int sz = Math.max(1, m);\n        int[] L = new int[sz], R = new int[sz];\n        int cnt = 0;\n        if (toks.length > 0) {\n            L[0] = -1; R[0] = -1; cnt = 1;\n            int[] q = new int[m + 1]; int qh = 0, qt = 0; q[qt++] = 0; int i = 1;\n            while (qh < qt && i < toks.length) {\n                int cur = q[qh++];\n                if (i < toks.length && !toks[i].equals(\"null\")) { L[cnt] = -1; R[cnt] = -1; L[cur] = cnt; q[qt++] = cnt; cnt++; }\n                i++;\n                if (i < toks.length && !toks[i].equals(\"null\")) { L[cnt] = -1; R[cnt] = -1; R[cur] = cnt; q[qt++] = cnt; cnt++; }\n                i++;\n            }\n        }\n        int leaves = 0;\n        for (int x = 0; x < cnt; x++) if (L[x] == -1 && R[x] == -1) leaves++;\n        System.out.println(leaves);\n    }\n}\n","python":"import sys\nlines = sys.stdin.read().split('\\n')\nm = int(lines[0])\ntoks = lines[1].split() if m > 0 else []\nL, R = [], []\ncnt = 0\nif toks:\n    L.append(-1); R.append(-1); cnt = 1\n    q = [0]; qh = 0; i = 1\n    while qh < len(q) and i < len(toks):\n        cur = q[qh]; qh += 1\n        if i < len(toks) and toks[i] != 'null':\n            L.append(-1); R.append(-1); L[cur] = cnt; q.append(cnt); cnt += 1\n        i += 1\n        if i < len(toks) and toks[i] != 'null':\n            L.append(-1); R.append(-1); R[cur] = cnt; q.append(cnt); cnt += 1\n        i += 1\nleaves = sum(1 for x in range(cnt) if L[x] == -1 and R[x] == -1)\nprint(leaves if toks else 0)\n","c":"#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\nint main(void) {\n    int m;\n    if (scanf(\"%d\", &m) != 1) return 0;\n    char **toks = malloc(sizeof(char*) * (m > 0 ? m : 1));\n    int t = 0;\n    for (int i = 0; i < m; i++) { toks[t] = malloc(16); scanf(\"%15s\", toks[t]); t++; }\n    int sz = m > 0 ? m : 1;\n    int *L = malloc(sizeof(int) * sz), *R = malloc(sizeof(int) * sz);\n    int cnt = 0;\n    if (t > 0) {\n        L[0] = -1; R[0] = -1; cnt = 1;\n        int *q = malloc(sizeof(int) * (m + 1)); int qh = 0, qt = 0; q[qt++] = 0; int i = 1;\n        while (qh < qt && i < t) {\n            int cur = q[qh++];\n            if (i < t && strcmp(toks[i], \"null\") != 0) { L[cnt] = -1; R[cnt] = -1; L[cur] = cnt; q[qt++] = cnt; cnt++; }\n            i++;\n            if (i < t && strcmp(toks[i], \"null\") != 0) { L[cnt] = -1; R[cnt] = -1; R[cur] = cnt; q[qt++] = cnt; cnt++; }\n            i++;\n        }\n        free(q);\n    }\n    int leaves = 0;\n    for (int x = 0; x < cnt; x++) if (L[x] == -1 && R[x] == -1) leaves++;\n    printf(\"%d\\n\", leaves);\n    return 0;\n}\n","cpp":"#include <iostream>\n#include <vector>\n#include <string>\n#include <sstream>\nusing namespace std;\nint main() {\n    ios::sync_with_stdio(false); cin.tie(nullptr);\n    int m; cin >> m; cin.ignore();\n    string line; getline(cin, line);\n    vector<string> toks;\n    { istringstream iss(line); string tk; while (iss >> tk) toks.push_back(tk); }\n    vector<int> L, R;\n    int cnt = 0;\n    if (!toks.empty()) {\n        L.push_back(-1); R.push_back(-1); cnt = 1;\n        vector<int> q{0}; size_t qh = 0, i = 1;\n        while (qh < q.size() && i < toks.size()) {\n            int cur = q[qh++];\n            if (i < toks.size() && toks[i] != \"null\") { L.push_back(-1); R.push_back(-1); L[cur] = cnt; q.push_back(cnt); cnt++; }\n            i++;\n            if (i < toks.size() && toks[i] != \"null\") { L.push_back(-1); R.push_back(-1); R[cur] = cnt; q.push_back(cnt); cnt++; }\n            i++;\n        }\n    }\n    int leaves = 0;\n    for (int x = 0; x < cnt; x++) if (L[x] == -1 && R[x] == -1) leaves++;\n    cout << leaves << \"\\n\";\n    return 0;\n}\n","javascript":"const lines = require('fs').readFileSync(0, 'utf8').split('\\n');\nconst m = Number(lines[0]);\nconst toks = m > 0 ? lines[1].trim().split(/\\s+/) : [];\nconst L = [], R = [];\nlet cnt = 0;\nif (toks.length) {\n    L.push(-1); R.push(-1); cnt = 1;\n    const q = [0]; let qh = 0, i = 1;\n    while (qh < q.length && i < toks.length) {\n        const cur = q[qh++];\n        if (i < toks.length && toks[i] !== 'null') { L.push(-1); R.push(-1); L[cur] = cnt; q.push(cnt); cnt++; }\n        i++;\n        if (i < toks.length && toks[i] !== 'null') { L.push(-1); R.push(-1); R[cur] = cnt; q.push(cnt); cnt++; }\n        i++;\n    }\n}\nlet leaves = 0;\nfor (let x = 0; x < cnt; x++) if (L[x] === -1 && R[x] === -1) leaves++;\nconsole.log(leaves);\n"}$px$::jsonb,
