values (
  'cp-practice-binary-tree-102', 'dt-practice-binary-tree', null,
  $px$Check Identical Trees$px$, $px$check-identical-trees$px$, $px$Easy$px$,
  $px$Given two binary trees, determine whether they have exactly the same structure and the same value at every corresponding node.

**Input Format**

The first line contains an integer `M1` and the second line the `M1` level-order tokens of tree A (blank if `M1` is 0).
The third line contains an integer `M2` and the fourth line the `M2` level-order tokens of tree B (blank if `M2` is 0).

**Output Format**

Print `1` if the trees are identical, otherwise print `0`.$px$,
  $px$[{"input":"3\n1 2 3\n3\n1 2 3","output":"1","explanation":"Both trees have matching structure and values."}]$px$::jsonb,
  $px$["0 <= number of nodes in each tree <= 5000","-1000000000 <= node value <= 1000000000"]$px$::jsonb,
  $px${"java":"import java.util.*;\nimport java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        // TODO: read the input, compute the answer, and print it\n    }\n}\n","python":"import sys\n\ndata = sys.stdin.read()\n# TODO: parse the input above and print the answer\n","c":"#include <stdio.h>\n\nint main(void) {\n    // TODO: read input with scanf / fgets, compute, print with printf\n    return 0;\n}\n","cpp":"#include <iostream>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    // TODO: read the input, compute the answer, and print it\n    return 0;\n}\n","javascript":"const data = require('fs').readFileSync(0, 'utf8');\n// TODO: parse the input above and print the answer\n"}$px$::jsonb,
  $px${"java":"import java.util.*;\nimport java.io.*;\npublic class Main {\n    static String[] vA, vB;\n    static int[] LA, RA, LB, RB;\n    static boolean same(int a, int b) {\n        if (a == -1 && b == -1) return true;\n        if (a == -1 || b == -1 || !vA[a].equals(vB[b])) return false;\n        return same(LA[a], LB[b]) && same(RA[a], RB[b]);\n    }\n    static Object[] build(int m, String[] toks) {\n        int sz = Math.max(1, m);\n        String[] v = new String[sz]; int[] L = new int[sz], R = new int[sz];\n        int cnt = 0;\n        if (toks.length > 0) {\n            v[0] = toks[0]; L[0] = -1; R[0] = -1; cnt = 1;\n            int[] q = new int[m + 1]; int qh = 0, qt = 0; q[qt++] = 0; int i = 1;\n            while (qh < qt && i < toks.length) {\n                int cur = q[qh++];\n                if (i < toks.length && !toks[i].equals(\"null\")) { v[cnt] = toks[i]; L[cnt] = -1; R[cnt] = -1; L[cur] = cnt; q[qt++] = cnt; cnt++; }\n                i++;\n                if (i < toks.length && !toks[i].equals(\"null\")) { v[cnt] = toks[i]; L[cnt] = -1; R[cnt] = -1; R[cur] = cnt; q[qt++] = cnt; cnt++; }\n                i++;\n            }\n        }\n        return new Object[]{v, L, R, cnt};\n    }\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        int m1 = Integer.parseInt(br.readLine().trim());\n        String l1 = br.readLine();\n        String[] tA = (m1 > 0 && l1 != null && !l1.trim().isEmpty()) ? l1.trim().split(\"\\\\s+\") : new String[0];\n        int m2 = Integer.parseInt(br.readLine().trim());\n        String l2 = br.readLine();\n        String[] tB = (m2 > 0 && l2 != null && !l2.trim().isEmpty()) ? l2.trim().split(\"\\\\s+\") : new String[0];\n        Object[] A = build(m1, tA), B = build(m2, tB);\n        vA = (String[]) A[0]; LA = (int[]) A[1]; RA = (int[]) A[2]; int cA = (int) A[3];\n        vB = (String[]) B[0]; LB = (int[]) B[1]; RB = (int[]) B[2]; int cB = (int) B[3];\n        System.out.println(same(cA > 0 ? 0 : -1, cB > 0 ? 0 : -1) ? 1 : 0);\n    }\n}\n","python":"import sys\nsys.setrecursionlimit(20000)\nlines = sys.stdin.read().split('\\n')\ndef build(m, toks):\n    val, L, R = [], [], []\n    if m > 0 and toks:\n        val.append(toks[0]); L.append(-1); R.append(-1)\n        q = [0]; qh = 0; i = 1\n        while qh < len(q) and i < len(toks):\n            cur = q[qh]; qh += 1\n            if i < len(toks) and toks[i] != 'null':\n                val.append(toks[i]); L.append(-1); R.append(-1); L[cur] = len(val) - 1; q.append(len(val) - 1)\n            i += 1\n            if i < len(toks) and toks[i] != 'null':\n                val.append(toks[i]); L.append(-1); R.append(-1); R[cur] = len(val) - 1; q.append(len(val) - 1)\n            i += 1\n    return val, L, R\nm1 = int(lines[0]); tA = lines[1].split() if m1 > 0 else []\nm2 = int(lines[2]); tB = lines[3].split() if m2 > 0 else []\nvA, LA, RA = build(m1, tA)\nvB, LB, RB = build(m2, tB)\ndef same(a, b):\n    if a == -1 and b == -1:\n        return True\n    if a == -1 or b == -1 or vA[a] != vB[b]:\n        return False\n    return same(LA[a], LB[b]) and same(RA[a], RB[b])\nra = 0 if vA else -1\nrb = 0 if vB else -1\nprint(1 if same(ra, rb) else 0)\n","c":"#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\nchar *vA[5001], *vB[5001];\nint LA[5001], RA[5001], LB[5001], RB[5001];\nint build(char **v, int *L, int *R) {\n    int m; scanf(\"%d\", &m);\n    char **toks = malloc(sizeof(char*) * (m > 0 ? m : 1));\n    for (int i = 0; i < m; i++) { toks[i] = malloc(16); scanf(\"%15s\", toks[i]); }\n    int cnt = 0;\n    if (m > 0) {\n        v[0] = toks[0]; L[0] = -1; R[0] = -1; cnt = 1;\n        int *q = malloc(sizeof(int) * (m + 1)); int qh = 0, qt = 0; q[qt++] = 0; int i = 1;\n        while (qh < qt && i < m) {\n            int cur = q[qh++];\n            if (i < m && strcmp(toks[i], \"null\") != 0) { v[cnt] = toks[i]; L[cnt] = -1; R[cnt] = -1; L[cur] = cnt; q[qt++] = cnt; cnt++; }\n            i++;\n            if (i < m && strcmp(toks[i], \"null\") != 0) { v[cnt] = toks[i]; L[cnt] = -1; R[cnt] = -1; R[cur] = cnt; q[qt++] = cnt; cnt++; }\n            i++;\n        }\n        free(q);\n    }\n    return cnt;\n}\nint same(int a, int b) {\n    if (a == -1 && b == -1) return 1;\n    if (a == -1 || b == -1 || strcmp(vA[a], vB[b]) != 0) return 0;\n    return same(LA[a], LB[b]) && same(RA[a], RB[b]);\n}\nint main(void) {\n    int cA = build(vA, LA, RA);\n    int cB = build(vB, LB, RB);\n    printf(\"%d\\n\", same(cA > 0 ? 0 : -1, cB > 0 ? 0 : -1));\n    return 0;\n}\n","cpp":"#include <iostream>\n#include <vector>\n#include <string>\n#include <sstream>\nusing namespace std;\nvector<string> vA, vB;\nvector<int> LA, RA, LB, RB;\nint build(vector<string>& v, vector<int>& L, vector<int>& R, const string& line) {\n    vector<string> toks;\n    { istringstream iss(line); string tk; while (iss >> tk) toks.push_back(tk); }\n    int cnt = 0;\n    if (!toks.empty()) {\n        v.push_back(toks[0]); L.push_back(-1); R.push_back(-1); cnt = 1;\n        vector<int> q{0}; size_t qh = 0, i = 1;\n        while (qh < q.size() && i < toks.size()) {\n            int cur = q[qh++];\n            if (i < toks.size() && toks[i] != \"null\") { v.push_back(toks[i]); L.push_back(-1); R.push_back(-1); L[cur] = cnt; q.push_back(cnt); cnt++; }\n            i++;\n            if (i < toks.size() && toks[i] != \"null\") { v.push_back(toks[i]); L.push_back(-1); R.push_back(-1); R[cur] = cnt; q.push_back(cnt); cnt++; }\n            i++;\n        }\n    }\n    return cnt;\n}\nbool same(int a, int b) {\n    if (a == -1 && b == -1) return true;\n    if (a == -1 || b == -1 || vA[a] != vB[b]) return false;\n    return same(LA[a], LB[b]) && same(RA[a], RB[b]);\n}\nint main() {\n    ios::sync_with_stdio(false); cin.tie(nullptr);\n    int m1; cin >> m1; cin.ignore();\n    string l1; getline(cin, l1);\n    int m2; cin >> m2; cin.ignore();\n    string l2; getline(cin, l2);\n    int cA = build(vA, LA, RA, l1);\n    int cB = build(vB, LB, RB, l2);\n    cout << (same(cA > 0 ? 0 : -1, cB > 0 ? 0 : -1) ? 1 : 0) << \"\\n\";\n    return 0;\n}\n","javascript":"const lines = require('fs').readFileSync(0, 'utf8').split('\\n');\nfunction build(line) {\n    const toks = line.trim() ? line.trim().split(/\\s+/) : [];\n    const v = [], L = [], R = [];\n    if (toks.length) {\n        v.push(toks[0]); L.push(-1); R.push(-1);\n        const q = [0]; let qh = 0, i = 1;\n        while (qh < q.length && i < toks.length) {\n            const cur = q[qh++];\n            if (i < toks.length && toks[i] !== 'null') { v.push(toks[i]); L.push(-1); R.push(-1); L[cur] = v.length - 1; q.push(v.length - 1); }\n            i++;\n            if (i < toks.length && toks[i] !== 'null') { v.push(toks[i]); L.push(-1); R.push(-1); R[cur] = v.length - 1; q.push(v.length - 1); }\n            i++;\n        }\n    }\n    return { v, L, R };\n}\nconst A = build(lines[1] || '');\nconst B = build(lines[3] || '');\nfunction same(a, b) {\n    if (a === -1 && b === -1) return true;\n    if (a === -1 || b === -1 || A.v[a] !== B.v[b]) return false;\n    return same(A.L[a], B.L[b]) && same(A.R[a], B.R[b]);\n}\nconsole.log(same(A.v.length ? 0 : -1, B.v.length ? 0 : -1) ? 1 : 0);\n"}$px$::jsonb,
