  $px$Diameter of Binary Tree$px$, $px$diameter-of-binary-tree$px$, $px$Medium$px$,
  $px$Find the diameter of a binary tree: the number of edges on the longest path between any two nodes (the path need not pass through the root).

**Input Format**

The first line contains an integer `M`, the number of level-order tokens.
The second line contains `M` space-separated tokens (integers or `null`).

**Output Format**

Print the diameter, measured in edges.$px$,
  $px$[{"input":"5\n1 2 3 4 5","output":"3","explanation":"One longest path is 4 -> 2 -> 1 -> 3, containing three edges."}]$px$::jsonb,
  $px$["1 <= number of nodes <= 5000","-1000000000 <= node value <= 1000000000"]$px$::jsonb,
  $px${"java":"import java.util.*;\nimport java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        // TODO: read the input, compute the answer, and print it\n    }\n}\n","python":"import sys\n\ndata = sys.stdin.read()\n# TODO: parse the input above and print the answer\n","c":"#include <stdio.h>\n\nint main(void) {\n    // TODO: read input with scanf / fgets, compute, print with printf\n    return 0;\n}\n","cpp":"#include <iostream>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    // TODO: read the input, compute the answer, and print it\n    return 0;\n}\n","javascript":"const data = require('fs').readFileSync(0, 'utf8');\n// TODO: parse the input above and print the answer\n"}$px$::jsonb,
  $px${"java":"import java.util.*;\nimport java.io.*;\npublic class Main {\n    static int[] L, R;\n    static int best = 0;\n    static int h(int x) {\n        if (x == -1) return 0;\n        int a = h(L[x]), b = h(R[x]);\n        best = Math.max(best, a + b);\n        return 1 + Math.max(a, b);\n    }\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        int m = Integer.parseInt(br.readLine().trim());\n        String line = br.readLine();\n        String[] toks = line.trim().split(\"\\\\s+\");\n        int sz = Math.max(1, m);\n        int[] Lt = new int[sz], Rt = new int[sz];\n        Lt[0] = -1; Rt[0] = -1; int cnt = 1;\n        int[] q = new int[m + 1]; int qh = 0, qt = 0; q[qt++] = 0; int i = 1;\n        while (qh < qt && i < toks.length) {\n            int cur = q[qh++];\n            if (i < toks.length && !toks[i].equals(\"null\")) { Lt[cnt] = -1; Rt[cnt] = -1; Lt[cur] = cnt; q[qt++] = cnt; cnt++; }\n            i++;\n            if (i < toks.length && !toks[i].equals(\"null\")) { Lt[cnt] = -1; Rt[cnt] = -1; Rt[cur] = cnt; q[qt++] = cnt; cnt++; }\n            i++;\n        }\n        L = Lt; R = Rt;\n        h(0);\n        System.out.println(best);\n    }\n}\n","python":"import sys\nsys.setrecursionlimit(20000)\nlines = sys.stdin.read().split('\\n')\nm = int(lines[0])\ntoks = lines[1].split() if m > 0 else []\nL, R = [], []\ncnt = 0\nif toks:\n    L.append(-1); R.append(-1); cnt = 1\n    q = [0]; qh = 0; i = 1\n    while qh < len(q) and i < len(toks):\n        cur = q[qh]; qh += 1\n        if i < len(toks) and toks[i] != 'null':\n            L.append(-1); R.append(-1); L[cur] = cnt; q.append(cnt); cnt += 1\n        i += 1\n        if i < len(toks) and toks[i] != 'null':\n            L.append(-1); R.append(-1); R[cur] = cnt; q.append(cnt); cnt += 1\n        i += 1\nbest = [0]\ndef h(x):\n    if x == -1:\n        return 0\n    a = h(L[x]); b = h(R[x])\n    best[0] = max(best[0], a + b)\n    return 1 + max(a, b)\nh(0)\nprint(best[0])\n","c":"#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\nint *L, *R, best = 0;\nint h(int x) {\n    if (x == -1) return 0;\n    int a = h(L[x]), b = h(R[x]);\n    if (a + b > best) best = a + b;\n    return 1 + (a > b ? a : b);\n}\nint main(void) {\n    int m;\n    if (scanf(\"%d\", &m) != 1) return 0;\n    char **toks = malloc(sizeof(char*) * m);\n    for (int i = 0; i < m; i++) { toks[i] = malloc(16); scanf(\"%15s\", toks[i]); }\n    L = malloc(sizeof(int) * m); R = malloc(sizeof(int) * m);\n    L[0] = -1; R[0] = -1; int cnt = 1;\n    int *q = malloc(sizeof(int) * (m + 1)); int qh = 0, qt = 0; q[qt++] = 0; int i = 1;\n    while (qh < qt && i < m) {\n        int cur = q[qh++];\n        if (i < m && strcmp(toks[i], \"null\") != 0) { L[cnt] = -1; R[cnt] = -1; L[cur] = cnt; q[qt++] = cnt; cnt++; }\n        i++;\n        if (i < m && strcmp(toks[i], \"null\") != 0) { L[cnt] = -1; R[cnt] = -1; R[cur] = cnt; q[qt++] = cnt; cnt++; }\n        i++;\n    }\n    h(0);\n    printf(\"%d\\n\", best);\n    return 0;\n}\n","cpp":"#include <iostream>\n#include <vector>\n#include <string>\n#include <sstream>\n#include <algorithm>\nusing namespace std;\nvector<int> L, R;\nint best = 0;\nint h(int x) {\n    if (x == -1) return 0;\n    int a = h(L[x]), b = h(R[x]);\n    best = max(best, a + b);\n    return 1 + max(a, b);\n}\nint main() {\n    ios::sync_with_stdio(false); cin.tie(nullptr);\n    int m; cin >> m; cin.ignore();\n    string line; getline(cin, line);\n    vector<string> toks;\n    { istringstream iss(line); string tk; while (iss >> tk) toks.push_back(tk); }\n    L.push_back(-1); R.push_back(-1); int cnt = 1;\n    vector<int> q{0}; size_t qh = 0, i = 1;\n    while (qh < q.size() && i < toks.size()) {\n        int cur = q[qh++];\n        if (i < toks.size() && toks[i] != \"null\") { L.push_back(-1); R.push_back(-1); L[cur] = cnt; q.push_back(cnt); cnt++; }\n        i++;\n        if (i < toks.size() && toks[i] != \"null\") { L.push_back(-1); R.push_back(-1); R[cur] = cnt; q.push_back(cnt); cnt++; }\n        i++;\n    }\n    h(0);\n    cout << best << \"\\n\";\n    return 0;\n}\n","javascript":"const lines = require('fs').readFileSync(0, 'utf8').split('\\n');\nconst m = Number(lines[0]);\nconst toks = lines[1].trim().split(/\\s+/);\nconst L = [-1], R = [-1];\nlet cnt = 1;\nconst q = [0]; let qh = 0, i = 1;\nwhile (qh < q.length && i < toks.length) {\n    const cur = q[qh++];\n    if (i < toks.length && toks[i] !== 'null') { L.push(-1); R.push(-1); L[cur] = cnt; q.push(cnt); cnt++; }\n    i++;\n    if (i < toks.length && toks[i] !== 'null') { L.push(-1); R.push(-1); R[cur] = cnt; q.push(cnt); cnt++; }\n    i++;\n}\nlet best = 0;\nfunction h(x) {\n    if (x === -1) return 0;\n    const a = h(L[x]), b = h(R[x]);\n    best = Math.max(best, a + b);\n    return 1 + Math.max(a, b);\n}\nh(0);\nconsole.log(best);\n"}$px$::jsonb,
