values (
  'cp-practice-binary-tree-105', 'dt-practice-binary-tree', null,
  $px$Lowest Common Ancestor$px$, $px$lowest-common-ancestor$px$, $px$Medium$px$,
  $px$Given a binary tree with distinct node values and two values `P` and `Q` that both appear in the tree, find the value of their lowest common ancestor (the deepest node that has both `P` and `Q` in its subtree).

**Input Format**

The first line contains an integer `M`, the number of level-order tokens.
The second line contains `M` space-separated tokens (integers or `null`).
The third line contains two integers `P` and `Q`.

**Output Format**

Print the value of the lowest common ancestor.$px$,
  $px$[{"input":"7\n3 5 1 6 2 0 8\n5 1","output":"3","explanation":"Node 3 is the deepest node that has both 5 and 1 in its subtree."}]$px$::jsonb,
  $px$["1 <= number of nodes <= 5000","All node values are distinct.","P and Q both appear in the tree."]$px$::jsonb,
  $px${"java":"import java.util.*;\nimport java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        // TODO: read the input, compute the answer, and print it\n    }\n}\n","python":"import sys\n\ndata = sys.stdin.read()\n# TODO: parse the input above and print the answer\n","c":"#include <stdio.h>\n\nint main(void) {\n    // TODO: read input with scanf / fgets, compute, print with printf\n    return 0;\n}\n","cpp":"#include <iostream>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    // TODO: read the input, compute the answer, and print it\n    return 0;\n}\n","javascript":"const data = require('fs').readFileSync(0, 'utf8');\n// TODO: parse the input above and print the answer\n"}$px$::jsonb,
  $px${"java":"import java.util.*;\nimport java.io.*;\npublic class Main {\n    static int[] L, R, V;\n    static int p, qv;\n    static int lca(int x) {\n        if (x == -1) return -1;\n        if (V[x] == p || V[x] == qv) return x;\n        int l = lca(L[x]), r = lca(R[x]);\n        if (l != -1 && r != -1) return x;\n        return l != -1 ? l : r;\n    }\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        int m = Integer.parseInt(br.readLine().trim());\n        String[] toks = br.readLine().trim().split(\"\\\\s+\");\n        StringTokenizer pq = new StringTokenizer(br.readLine());\n        p = Integer.parseInt(pq.nextToken()); qv = Integer.parseInt(pq.nextToken());\n        int sz = Math.max(1, m);\n        L = new int[sz]; R = new int[sz]; V = new int[sz];\n        V[0] = Integer.parseInt(toks[0]); L[0] = -1; R[0] = -1; int cnt = 1;\n        int[] qu = new int[m + 1]; int qh = 0, qt = 0; qu[qt++] = 0; int i = 1;\n        while (qh < qt && i < toks.length) {\n            int cur = qu[qh++];\n            if (i < toks.length && !toks[i].equals(\"null\")) { V[cnt] = Integer.parseInt(toks[i]); L[cnt] = -1; R[cnt] = -1; L[cur] = cnt; qu[qt++] = cnt; cnt++; }\n            i++;\n            if (i < toks.length && !toks[i].equals(\"null\")) { V[cnt] = Integer.parseInt(toks[i]); L[cnt] = -1; R[cnt] = -1; R[cur] = cnt; qu[qt++] = cnt; cnt++; }\n            i++;\n        }\n        System.out.println(V[lca(0)]);\n    }\n}\n","python":"import sys\nsys.setrecursionlimit(20000)\nlines = sys.stdin.read().split('\\n')\nm = int(lines[0])\ntoks = lines[1].split()\np, qv = map(int, lines[2].split())\nV, L, R = [], [], []\nV.append(int(toks[0])); L.append(-1); R.append(-1)\nqu = [0]; qh = 0; i = 1; cnt = 1\nwhile qh < len(qu) and i < len(toks):\n    cur = qu[qh]; qh += 1\n    if i < len(toks) and toks[i] != 'null':\n        V.append(int(toks[i])); L.append(-1); R.append(-1); L[cur] = cnt; qu.append(cnt); cnt += 1\n    i += 1\n    if i < len(toks) and toks[i] != 'null':\n        V.append(int(toks[i])); L.append(-1); R.append(-1); R[cur] = cnt; qu.append(cnt); cnt += 1\n    i += 1\ndef lca(x):\n    if x == -1:\n        return -1\n    if V[x] == p or V[x] == qv:\n        return x\n    l = lca(L[x]); r = lca(R[x])\n    if l != -1 and r != -1:\n        return x\n    return l if l != -1 else r\nprint(V[lca(0)])\n","c":"#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\nint *L, *R;\nlong long *V;\nlong long p, qv;\nint lca(int x) {\n    if (x == -1) return -1;\n    if (V[x] == p || V[x] == qv) return x;\n    int l = lca(L[x]), r = lca(R[x]);\n    if (l != -1 && r != -1) return x;\n    return l != -1 ? l : r;\n}\nint main(void) {\n    int m;\n    if (scanf(\"%d\", &m) != 1) return 0;\n    char **toks = malloc(sizeof(char*) * m);\n    for (int i = 0; i < m; i++) { toks[i] = malloc(16); scanf(\"%15s\", toks[i]); }\n    scanf(\"%lld %lld\", &p, &qv);\n    L = malloc(sizeof(int) * m); R = malloc(sizeof(int) * m); V = malloc(sizeof(long long) * m);\n    V[0] = atoll(toks[0]); L[0] = -1; R[0] = -1; int cnt = 1;\n    int *qu = malloc(sizeof(int) * (m + 1)); int qh = 0, qt = 0; qu[qt++] = 0; int i = 1;\n    while (qh < qt && i < m) {\n        int cur = qu[qh++];\n        if (i < m && strcmp(toks[i], \"null\") != 0) { V[cnt] = atoll(toks[i]); L[cnt] = -1; R[cnt] = -1; L[cur] = cnt; qu[qt++] = cnt; cnt++; }\n        i++;\n        if (i < m && strcmp(toks[i], \"null\") != 0) { V[cnt] = atoll(toks[i]); L[cnt] = -1; R[cnt] = -1; R[cur] = cnt; qu[qt++] = cnt; cnt++; }\n        i++;\n    }\n    printf(\"%lld\\n\", V[lca(0)]);\n    return 0;\n}\n","cpp":"#include <iostream>\n#include <vector>\n#include <string>\n#include <sstream>\nusing namespace std;\nvector<int> L, R;\nvector<long long> V;\nlong long p, qv;\nint lca(int x) {\n    if (x == -1) return -1;\n    if (V[x] == p || V[x] == qv) return x;\n    int l = lca(L[x]), r = lca(R[x]);\n    if (l != -1 && r != -1) return x;\n    return l != -1 ? l : r;\n}\nint main() {\n    ios::sync_with_stdio(false); cin.tie(nullptr);\n    int m; cin >> m; cin.ignore();\n    string line; getline(cin, line);\n    cin >> p >> qv;\n    vector<string> toks;\n    { istringstream iss(line); string tk; while (iss >> tk) toks.push_back(tk); }\n    V.push_back(stoll(toks[0])); L.push_back(-1); R.push_back(-1); int cnt = 1;\n    vector<int> qu{0}; size_t qh = 0, i = 1;\n    while (qh < qu.size() && i < toks.size()) {\n        int cur = qu[qh++];\n        if (i < toks.size() && toks[i] != \"null\") { V.push_back(stoll(toks[i])); L.push_back(-1); R.push_back(-1); L[cur] = cnt; qu.push_back(cnt); cnt++; }\n        i++;\n        if (i < toks.size() && toks[i] != \"null\") { V.push_back(stoll(toks[i])); L.push_back(-1); R.push_back(-1); R[cur] = cnt; qu.push_back(cnt); cnt++; }\n        i++;\n    }\n    cout << V[lca(0)] << \"\\n\";\n    return 0;\n}\n","javascript":"const lines = require('fs').readFileSync(0, 'utf8').split('\\n');\nconst m = Number(lines[0]);\nconst toks = lines[1].trim().split(/\\s+/);\nconst [p, qv] = lines[2].trim().split(/\\s+/).map(Number);\nconst V = [Number(toks[0])], L = [-1], R = [-1];\nlet cnt = 1;\nconst qu = [0]; let qh = 0, i = 1;\nwhile (qh < qu.length && i < toks.length) {\n    const cur = qu[qh++];\n    if (i < toks.length && toks[i] !== 'null') { V.push(Number(toks[i])); L.push(-1); R.push(-1); L[cur] = cnt; qu.push(cnt); cnt++; }\n    i++;\n    if (i < toks.length && toks[i] !== 'null') { V.push(Number(toks[i])); L.push(-1); R.push(-1); R[cur] = cnt; qu.push(cnt); cnt++; }\n    i++;\n}\nfunction lca(x) {\n    if (x === -1) return -1;\n    if (V[x] === p || V[x] === qv) return x;\n    const l = lca(L[x]), r = lca(R[x]);\n    if (l !== -1 && r !== -1) return x;\n    return l !== -1 ? l : r;\n}\nconsole.log(V[lca(0)]);\n"}$px$::jsonb,
