values (
  'cp-practice-binary-tree-106', 'dt-practice-binary-tree', null,
  $px$Zigzag Level Order Traversal$px$, $px$zigzag-level-order-traversal$px$, $px$Medium$px$,
  $px$Traverse a binary tree level by level, but alternate the direction on each level: the first level left-to-right, the second right-to-left, and so on.

**Input Format**

The first line contains an integer `M`, the number of level-order tokens.
The second line contains `M` space-separated tokens (integers or `null`).

**Output Format**

Print each level on its own line (in the zigzag direction), values separated by single spaces. Print nothing for an empty tree.$px$,
  $px$[{"input":"7\n3 9 20 null null 15 7","output":"3\n20 9\n15 7","explanation":"Level 0 left-to-right, level 1 right-to-left, level 2 left-to-right."}]$px$::jsonb,
  $px$["0 <= number of nodes <= 5000","-1000000000 <= node value <= 1000000000"]$px$::jsonb,
  $px${"java":"import java.util.*;\nimport java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        // TODO: read the input, compute the answer, and print it\n    }\n}\n","python":"import sys\n\ndata = sys.stdin.read()\n# TODO: parse the input above and print the answer\n","c":"#include <stdio.h>\n\nint main(void) {\n    // TODO: read input with scanf / fgets, compute, print with printf\n    return 0;\n}\n","cpp":"#include <iostream>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    // TODO: read the input, compute the answer, and print it\n    return 0;\n}\n","javascript":"const data = require('fs').readFileSync(0, 'utf8');\n// TODO: parse the input above and print the answer\n"}$px$::jsonb,
  $px${"java":"import java.util.*;\nimport java.io.*;\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        int m = Integer.parseInt(br.readLine().trim());\n        String line = br.readLine();\n        String[] toks = (m > 0 && line != null) ? line.trim().split(\"\\\\s+\") : new String[0];\n        int sz = Math.max(1, m);\n        int[] L = new int[sz], R = new int[sz]; long[] V = new long[sz];\n        int cnt = 0;\n        if (toks.length > 0) {\n            V[0] = Long.parseLong(toks[0]); L[0] = -1; R[0] = -1; cnt = 1;\n            int[] q = new int[m + 1]; int qh = 0, qt = 0; q[qt++] = 0; int i = 1;\n            while (qh < qt && i < toks.length) {\n                int cur = q[qh++];\n                if (i < toks.length && !toks[i].equals(\"null\")) { V[cnt] = Long.parseLong(toks[i]); L[cnt] = -1; R[cnt] = -1; L[cur] = cnt; q[qt++] = cnt; cnt++; }\n                i++;\n                if (i < toks.length && !toks[i].equals(\"null\")) { V[cnt] = Long.parseLong(toks[i]); L[cnt] = -1; R[cnt] = -1; R[cur] = cnt; q[qt++] = cnt; cnt++; }\n                i++;\n            }\n        }\n        StringBuilder sb = new StringBuilder();\n        if (cnt > 0) {\n            List<Integer> level = new ArrayList<>();\n            level.add(0);\n            boolean ltr = true;\n            while (!level.isEmpty()) {\n                List<Long> vals = new ArrayList<>();\n                for (int x : level) vals.add(V[x]);\n                if (!ltr) Collections.reverse(vals);\n                for (int k = 0; k < vals.size(); k++) { if (k > 0) sb.append(' '); sb.append(vals.get(k)); }\n                sb.append('\\n');\n                List<Integer> nxt = new ArrayList<>();\n                for (int x : level) { if (L[x] != -1) nxt.add(L[x]); if (R[x] != -1) nxt.add(R[x]); }\n                level = nxt;\n                ltr = !ltr;\n            }\n        }\n        System.out.print(sb);\n    }\n}\n","python":"import sys\nlines = sys.stdin.read().split('\\n')\nm = int(lines[0])\ntoks = lines[1].split() if m > 0 else []\nV, L, R = [], [], []\ncnt = 0\nif toks:\n    V.append(int(toks[0])); L.append(-1); R.append(-1); cnt = 1\n    q = [0]; qh = 0; i = 1\n    while qh < len(q) and i < len(toks):\n        cur = q[qh]; qh += 1\n        if i < len(toks) and toks[i] != 'null':\n            V.append(int(toks[i])); L.append(-1); R.append(-1); L[cur] = cnt; q.append(cnt); cnt += 1\n        i += 1\n        if i < len(toks) and toks[i] != 'null':\n            V.append(int(toks[i])); L.append(-1); R.append(-1); R[cur] = cnt; q.append(cnt); cnt += 1\n        i += 1\nout = []\nif cnt > 0:\n    level = [0]\n    ltr = True\n    while level:\n        vals = [V[x] for x in level]\n        out.append(' '.join(map(str, vals if ltr else vals[::-1])))\n        nxt = []\n        for x in level:\n            if L[x] != -1: nxt.append(L[x])\n            if R[x] != -1: nxt.append(R[x])\n        level = nxt\n        ltr = not ltr\nprint('\\n'.join(out))\n","c":"#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\nint main(void) {\n    int m;\n    if (scanf(\"%d\", &m) != 1) return 0;\n    char **toks = malloc(sizeof(char*) * (m > 0 ? m : 1));\n    int t = 0;\n    for (int i = 0; i < m; i++) { toks[t] = malloc(16); scanf(\"%15s\", toks[t]); t++; }\n    int sz = m > 0 ? m : 1;\n    int *L = malloc(sizeof(int) * sz), *R = malloc(sizeof(int) * sz);\n    long long *V = malloc(sizeof(long long) * sz);\n    int cnt = 0;\n    if (t > 0) {\n        V[0] = atoll(toks[0]); L[0] = -1; R[0] = -1; cnt = 1;\n        int *q = malloc(sizeof(int) * (m + 1)); int qh = 0, qt = 0; q[qt++] = 0; int i = 1;\n        while (qh < qt && i < t) {\n            int cur = q[qh++];\n            if (i < t && strcmp(toks[i], \"null\") != 0) { V[cnt] = atoll(toks[i]); L[cnt] = -1; R[cnt] = -1; L[cur] = cnt; q[qt++] = cnt; cnt++; }\n            i++;\n            if (i < t && strcmp(toks[i], \"null\") != 0) { V[cnt] = atoll(toks[i]); L[cnt] = -1; R[cnt] = -1; R[cur] = cnt; q[qt++] = cnt; cnt++; }\n            i++;\n        }\n        free(q);\n    }\n    if (cnt > 0) {\n        int *cur = malloc(sizeof(int) * (cnt + 1));\n        int *nxt = malloc(sizeof(int) * (cnt + 1));\n        int cs = 0; cur[cs++] = 0; int ltr = 1;\n        while (cs > 0) {\n            if (ltr) { for (int k = 0; k < cs; k++) printf(\"%lld%s\", V[cur[k]], k + 1 < cs ? \" \" : \"\\n\"); }\n            else { for (int k = cs - 1; k >= 0; k--) printf(\"%lld%s\", V[cur[k]], k > 0 ? \" \" : \"\\n\"); }\n            int ns = 0;\n            for (int k = 0; k < cs; k++) { if (L[cur[k]] != -1) nxt[ns++] = L[cur[k]]; if (R[cur[k]] != -1) nxt[ns++] = R[cur[k]]; }\n            for (int k = 0; k < ns; k++) cur[k] = nxt[k];\n            cs = ns; ltr = !ltr;\n        }\n        free(cur); free(nxt);\n    }\n    return 0;\n}\n","cpp":"#include <iostream>\n#include <vector>\n#include <string>\n#include <sstream>\n#include <algorithm>\nusing namespace std;\nint main() {\n    ios::sync_with_stdio(false); cin.tie(nullptr);\n    int m; cin >> m; cin.ignore();\n    string line; getline(cin, line);\n    vector<string> toks;\n    { istringstream iss(line); string tk; while (iss >> tk) toks.push_back(tk); }\n    vector<int> L, R; vector<long long> V;\n    int cnt = 0;\n    if (!toks.empty()) {\n        V.push_back(stoll(toks[0])); L.push_back(-1); R.push_back(-1); cnt = 1;\n        vector<int> q{0}; size_t qh = 0, i = 1;\n        while (qh < q.size() && i < toks.size()) {\n            int cur = q[qh++];\n            if (i < toks.size() && toks[i] != \"null\") { V.push_back(stoll(toks[i])); L.push_back(-1); R.push_back(-1); L[cur] = cnt; q.push_back(cnt); cnt++; }\n            i++;\n            if (i < toks.size() && toks[i] != \"null\") { V.push_back(stoll(toks[i])); L.push_back(-1); R.push_back(-1); R[cur] = cnt; q.push_back(cnt); cnt++; }\n            i++;\n        }\n    }\n    if (cnt > 0) {\n        vector<int> level{0};\n        bool ltr = true;\n        while (!level.empty()) {\n            vector<long long> vals;\n            for (int x : level) vals.push_back(V[x]);\n            if (!ltr) reverse(vals.begin(), vals.end());\n            for (size_t k = 0; k < vals.size(); k++) { if (k) cout << ' '; cout << vals[k]; }\n            cout << '\\n';\n            vector<int> nxt;\n            for (int x : level) { if (L[x] != -1) nxt.push_back(L[x]); if (R[x] != -1) nxt.push_back(R[x]); }\n            level = nxt; ltr = !ltr;\n        }\n    }\n    return 0;\n}\n","javascript":"const lines = require('fs').readFileSync(0, 'utf8').split('\\n');\nconst m = Number(lines[0]);\nconst toks = m > 0 ? lines[1].trim().split(/\\s+/) : [];\nconst V = [], L = [], R = [];\nlet cnt = 0;\nif (toks.length) {\n    V.push(Number(toks[0])); L.push(-1); R.push(-1); cnt = 1;\n    const q = [0]; let qh = 0, i = 1;\n    while (qh < q.length && i < toks.length) {\n        const cur = q[qh++];\n        if (i < toks.length && toks[i] !== 'null') { V.push(Number(toks[i])); L.push(-1); R.push(-1); L[cur] = cnt; q.push(cnt); cnt++; }\n        i++;\n        if (i < toks.length && toks[i] !== 'null') { V.push(Number(toks[i])); L.push(-1); R.push(-1); R[cur] = cnt; q.push(cnt); cnt++; }\n        i++;\n    }\n}\nconst out = [];\nif (cnt > 0) {\n    let level = [0], ltr = true;\n    while (level.length) {\n        const vals = level.map((x) => V[x]);\n        out.push((ltr ? vals : vals.slice().reverse()).join(' '));\n        const nxt = [];\n        for (const x of level) { if (L[x] !== -1) nxt.push(L[x]); if (R[x] !== -1) nxt.push(R[x]); }\n        level = nxt; ltr = !ltr;\n    }\n}\nconsole.log(out.join('\\n'));\n"}$px$::jsonb,
