values (
  'cp-practice-binary-tree-107', 'dt-practice-binary-tree', null,
  $px$Serialize and Deserialize Binary Tree$px$, $px$serialize-and-deserialize-binary-tree$px$, $px$Hard$px$,
  $px$Build a binary tree from its level-order description, then serialize it back to a canonical level-order form: perform a breadth-first walk emitting each node's value, and `null` for every missing child of a real node. Trailing `null` tokens are removed.

**Input Format**

The first line contains an integer `M`, the number of level-order tokens.
The second line contains `M` space-separated tokens (integers or `null`).

**Output Format**

Print the canonical serialization on one line, tokens separated by single spaces. Print an empty line for an empty tree.$px$,
  $px$[{"input":"7\n1 2 3 null null 4 5","output":"1 2 3 null null 4 5","explanation":"The rebuilt tree serializes to the same canonical form."}]$px$::jsonb,
  $px$["0 <= number of nodes <= 5000","-1000000000 <= node value <= 1000000000"]$px$::jsonb,
  $px${"java":"import java.util.*;\nimport java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        // TODO: read the input, compute the answer, and print it\n    }\n}\n","python":"import sys\n\ndata = sys.stdin.read()\n# TODO: parse the input above and print the answer\n","c":"#include <stdio.h>\n\nint main(void) {\n    // TODO: read input with scanf / fgets, compute, print with printf\n    return 0;\n}\n","cpp":"#include <iostream>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    // TODO: read the input, compute the answer, and print it\n    return 0;\n}\n","javascript":"const data = require('fs').readFileSync(0, 'utf8');\n// TODO: parse the input above and print the answer\n"}$px$::jsonb,
  $px${"java":"import java.util.*;\nimport java.io.*;\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        int m = Integer.parseInt(br.readLine().trim());\n        String line = br.readLine();\n        String[] toks = (m > 0 && line != null) ? line.trim().split(\"\\\\s+\") : new String[0];\n        int sz = Math.max(1, m);\n        String[] V = new String[sz]; int[] L = new int[sz], R = new int[sz];\n        int cnt = 0;\n        if (toks.length > 0) {\n            V[0] = toks[0]; L[0] = -1; R[0] = -1; cnt = 1;\n            int[] q = new int[m + 1]; int qh = 0, qt = 0; q[qt++] = 0; int i = 1;\n            while (qh < qt && i < toks.length) {\n                int cur = q[qh++];\n                if (i < toks.length && !toks[i].equals(\"null\")) { V[cnt] = toks[i]; L[cnt] = -1; R[cnt] = -1; L[cur] = cnt; q[qt++] = cnt; cnt++; }\n                i++;\n                if (i < toks.length && !toks[i].equals(\"null\")) { V[cnt] = toks[i]; L[cnt] = -1; R[cnt] = -1; R[cur] = cnt; q[qt++] = cnt; cnt++; }\n                i++;\n            }\n        }\n        ArrayList<String> out = new ArrayList<>();\n        if (cnt > 0) {\n            ArrayDeque<Integer> bq = new ArrayDeque<>();\n            bq.add(0);\n            while (!bq.isEmpty()) {\n                int x = bq.poll();\n                if (x == -1) { out.add(\"null\"); continue; }\n                out.add(V[x]);\n                bq.add(L[x]); bq.add(R[x]);\n            }\n            while (!out.isEmpty() && out.get(out.size() - 1).equals(\"null\")) out.remove(out.size() - 1);\n        }\n        System.out.println(String.join(\" \", out));\n    }\n}\n","python":"import sys\nlines = sys.stdin.read().split('\\n')\nm = int(lines[0])\ntoks = lines[1].split() if m > 0 else []\nV, L, R = [], [], []\ncnt = 0\nif toks:\n    V.append(toks[0]); L.append(-1); R.append(-1); cnt = 1\n    q = [0]; qh = 0; i = 1\n    while qh < len(q) and i < len(toks):\n        cur = q[qh]; qh += 1\n        if i < len(toks) and toks[i] != 'null':\n            V.append(toks[i]); L.append(-1); R.append(-1); L[cur] = cnt; q.append(cnt); cnt += 1\n        i += 1\n        if i < len(toks) and toks[i] != 'null':\n            V.append(toks[i]); L.append(-1); R.append(-1); R[cur] = cnt; q.append(cnt); cnt += 1\n        i += 1\nout = []\nif cnt > 0:\n    q = [0]; qh = 0\n    while qh < len(q):\n        x = q[qh]; qh += 1\n        if x == -1:\n            out.append('null')\n        else:\n            out.append(V[x])\n            q.append(L[x]); q.append(R[x])\n    while out and out[-1] == 'null':\n        out.pop()\nprint(' '.join(out))\n","c":"#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\nint main(void) {\n    int m;\n    if (scanf(\"%d\", &m) != 1) return 0;\n    char **toks = malloc(sizeof(char*) * (m > 0 ? m : 1));\n    int t = 0;\n    for (int i = 0; i < m; i++) { toks[t] = malloc(16); scanf(\"%15s\", toks[t]); t++; }\n    int sz = m > 0 ? m : 1;\n    char **V = malloc(sizeof(char*) * sz);\n    int *L = malloc(sizeof(int) * sz), *R = malloc(sizeof(int) * sz);\n    int cnt = 0;\n    if (t > 0) {\n        V[0] = toks[0]; L[0] = -1; R[0] = -1; cnt = 1;\n        int *q = malloc(sizeof(int) * (m + 1)); int qh = 0, qt = 0; q[qt++] = 0; int i = 1;\n        while (qh < qt && i < t) {\n            int cur = q[qh++];\n            if (i < t && strcmp(toks[i], \"null\") != 0) { V[cnt] = toks[i]; L[cnt] = -1; R[cnt] = -1; L[cur] = cnt; q[qt++] = cnt; cnt++; }\n            i++;\n            if (i < t && strcmp(toks[i], \"null\") != 0) { V[cnt] = toks[i]; L[cnt] = -1; R[cnt] = -1; R[cur] = cnt; q[qt++] = cnt; cnt++; }\n            i++;\n        }\n        free(q);\n    }\n    char **out = malloc(sizeof(char*) * (2 * sz + 2));\n    int on = 0;\n    if (cnt > 0) {\n        int *bq = malloc(sizeof(int) * (2 * cnt + 4)); int bh = 0, bt = 0; bq[bt++] = 0;\n        while (bh < bt) {\n            int x = bq[bh++];\n            if (x == -1) { out[on++] = \"null\"; continue; }\n            out[on++] = V[x];\n            bq[bt++] = L[x]; bq[bt++] = R[x];\n        }\n        while (on > 0 && strcmp(out[on - 1], \"null\") == 0) on--;\n        free(bq);\n    }\n    for (int i = 0; i < on; i++) printf(\"%s%s\", out[i], i + 1 < on ? \" \" : \"\");\n    printf(\"\\n\");\n    return 0;\n}\n","cpp":"#include <iostream>\n#include <vector>\n#include <string>\n#include <sstream>\n#include <deque>\nusing namespace std;\nint main() {\n    ios::sync_with_stdio(false); cin.tie(nullptr);\n    int m; cin >> m; cin.ignore();\n    string line; getline(cin, line);\n    vector<string> toks;\n    { istringstream iss(line); string tk; while (iss >> tk) toks.push_back(tk); }\n    vector<string> V; vector<int> L, R;\n    int cnt = 0;\n    if (!toks.empty()) {\n        V.push_back(toks[0]); L.push_back(-1); R.push_back(-1); cnt = 1;\n        vector<int> q{0}; size_t qh = 0, i = 1;\n        while (qh < q.size() && i < toks.size()) {\n            int cur = q[qh++];\n            if (i < toks.size() && toks[i] != \"null\") { V.push_back(toks[i]); L.push_back(-1); R.push_back(-1); L[cur] = cnt; q.push_back(cnt); cnt++; }\n            i++;\n            if (i < toks.size() && toks[i] != \"null\") { V.push_back(toks[i]); L.push_back(-1); R.push_back(-1); R[cur] = cnt; q.push_back(cnt); cnt++; }\n            i++;\n        }\n    }\n    vector<string> out;\n    if (cnt > 0) {\n        deque<int> bq;\n        bq.push_back(0);\n        while (!bq.empty()) {\n            int x = bq.front(); bq.pop_front();\n            if (x == -1) { out.push_back(\"null\"); continue; }\n            out.push_back(V[x]);\n            bq.push_back(L[x]); bq.push_back(R[x]);\n        }\n        while (!out.empty() && out.back() == \"null\") out.pop_back();\n    }\n    for (size_t k = 0; k < out.size(); k++) { if (k) cout << ' '; cout << out[k]; }\n    cout << \"\\n\";\n    return 0;\n}\n","javascript":"const lines = require('fs').readFileSync(0, 'utf8').split('\\n');\nconst m = Number(lines[0]);\nconst toks = m > 0 ? lines[1].trim().split(/\\s+/) : [];\nconst V = [], L = [], R = [];\nlet cnt = 0;\nif (toks.length) {\n    V.push(toks[0]); L.push(-1); R.push(-1); cnt = 1;\n    const q = [0]; let qh = 0, i = 1;\n    while (qh < q.length && i < toks.length) {\n        const cur = q[qh++];\n        if (i < toks.length && toks[i] !== 'null') { V.push(toks[i]); L.push(-1); R.push(-1); L[cur] = cnt; q.push(cnt); cnt++; }\n        i++;\n        if (i < toks.length && toks[i] !== 'null') { V.push(toks[i]); L.push(-1); R.push(-1); R[cur] = cnt; q.push(cnt); cnt++; }\n        i++;\n    }\n}\nconst out = [];\nif (cnt > 0) {\n    const bq = [0]; let bh = 0;\n    while (bh < bq.length) {\n        const x = bq[bh++];\n        if (x === -1) { out.push('null'); continue; }\n        out.push(V[x]);\n        bq.push(L[x]); bq.push(R[x]);\n    }\n    while (out.length && out[out.length - 1] === 'null') out.pop();\n}\nconsole.log(out.join(' '));\n"}$px$::jsonb,
