values (
  'cp-practice-binary-tree-109', 'dt-practice-binary-tree', null,
  $px$Boundary Traversal$px$, $px$boundary-traversal$px$, $px$Hard$px$,
  $px$Print the boundary of a binary tree in anti-clockwise order, without repeating any node: the root, then the left boundary top-down (excluding leaves), then all leaves left-to-right, then the right boundary bottom-up (excluding leaves).

**Input Format**

The first line contains an integer `M`, the number of level-order tokens.
The second line contains `M` space-separated tokens (integers or `null`).

**Output Format**

Print the boundary node values separated by single spaces.$px$,
  $px$[{"input":"7\n1 2 3 4 5 6 7","output":"1 2 4 5 6 7 3","explanation":"Root 1, left boundary 2, leaves 4 5 6 7, right boundary 3."}]$px$::jsonb,
  $px$["1 <= number of nodes <= 5000","-1000000000 <= node value <= 1000000000"]$px$::jsonb,
  $px${"java":"import java.util.*;\nimport java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        // TODO: read the input, compute the answer, and print it\n    }\n}\n","python":"import sys\n\ndata = sys.stdin.read()\n# TODO: parse the input above and print the answer\n","c":"#include <stdio.h>\n\nint main(void) {\n    // TODO: read input with scanf / fgets, compute, print with printf\n    return 0;\n}\n","cpp":"#include <iostream>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    // TODO: read the input, compute the answer, and print it\n    return 0;\n}\n","javascript":"const data = require('fs').readFileSync(0, 'utf8');\n// TODO: parse the input above and print the answer\n"}$px$::jsonb,
  $px${"java":"import java.util.*;\nimport java.io.*;\npublic class Main {\n    static int[] L, R, V;\n    static ArrayList<Integer> res = new ArrayList<>();\n    static boolean leaf(int x) { return L[x] == -1 && R[x] == -1; }\n    static void addLeaves(int x) {\n        if (leaf(x)) { res.add(V[x]); return; }\n        if (L[x] != -1) addLeaves(L[x]);\n        if (R[x] != -1) addLeaves(R[x]);\n    }\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        int m = Integer.parseInt(br.readLine().trim());\n        String[] toks = br.readLine().trim().split(\"\\\\s+\");\n        int sz = Math.max(1, m);\n        L = new int[sz]; R = new int[sz]; V = new int[sz];\n        V[0] = Integer.parseInt(toks[0]); L[0] = -1; R[0] = -1; int cnt = 1;\n        int[] q = new int[m + 1]; int qh = 0, qt = 0; q[qt++] = 0; int i = 1;\n        while (qh < qt && i < toks.length) {\n            int cur = q[qh++];\n            if (i < toks.length && !toks[i].equals(\"null\")) { V[cnt] = Integer.parseInt(toks[i]); L[cnt] = -1; R[cnt] = -1; L[cur] = cnt; q[qt++] = cnt; cnt++; }\n            i++;\n            if (i < toks.length && !toks[i].equals(\"null\")) { V[cnt] = Integer.parseInt(toks[i]); L[cnt] = -1; R[cnt] = -1; R[cur] = cnt; q[qt++] = cnt; cnt++; }\n            i++;\n        }\n        if (!leaf(0)) res.add(V[0]);\n        int cur = L[0];\n        while (cur != -1) {\n            if (!leaf(cur)) res.add(V[cur]);\n            cur = L[cur] != -1 ? L[cur] : R[cur];\n        }\n        addLeaves(0);\n        ArrayDeque<Integer> stack = new ArrayDeque<>();\n        cur = R[0];\n        while (cur != -1) {\n            if (!leaf(cur)) stack.push(V[cur]);\n            cur = R[cur] != -1 ? R[cur] : L[cur];\n        }\n        while (!stack.isEmpty()) res.add(stack.pop());\n        StringBuilder sb = new StringBuilder();\n        for (int k = 0; k < res.size(); k++) { if (k > 0) sb.append(' '); sb.append(res.get(k)); }\n        System.out.println(sb.toString());\n    }\n}\n","python":"import sys\nsys.setrecursionlimit(20000)\nlines = sys.stdin.read().split('\\n')\nm = int(lines[0])\ntoks = lines[1].split()\nV, L, R = [], [], []\nV.append(int(toks[0])); L.append(-1); R.append(-1)\nq = [0]; qh = 0; i = 1; cnt = 1\nwhile qh < len(q) and i < len(toks):\n    cur = q[qh]; qh += 1\n    if i < len(toks) and toks[i] != 'null':\n        V.append(int(toks[i])); L.append(-1); R.append(-1); L[cur] = cnt; q.append(cnt); cnt += 1\n    i += 1\n    if i < len(toks) and toks[i] != 'null':\n        V.append(int(toks[i])); L.append(-1); R.append(-1); R[cur] = cnt; q.append(cnt); cnt += 1\n    i += 1\ndef leaf(x):\n    return L[x] == -1 and R[x] == -1\nres = []\nif not leaf(0):\n    res.append(V[0])\ncur = L[0]\nwhile cur != -1:\n    if not leaf(cur):\n        res.append(V[cur])\n    cur = L[cur] if L[cur] != -1 else R[cur]\ndef addLeaves(x):\n    if leaf(x):\n        res.append(V[x])\n        return\n    if L[x] != -1:\n        addLeaves(L[x])\n    if R[x] != -1:\n        addLeaves(R[x])\naddLeaves(0)\nstack = []\ncur = R[0]\nwhile cur != -1:\n    if not leaf(cur):\n        stack.append(V[cur])\n    cur = R[cur] if R[cur] != -1 else L[cur]\nres.extend(reversed(stack))\nprint(' '.join(map(str, res)))\n","c":"#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\nint *L, *R;\nlong long *V;\nlong long res[5001];\nint rn = 0;\nint leaf(int x) { return L[x] == -1 && R[x] == -1; }\nvoid addLeaves(int x) {\n    if (leaf(x)) { res[rn++] = V[x]; return; }\n    if (L[x] != -1) addLeaves(L[x]);\n    if (R[x] != -1) addLeaves(R[x]);\n}\nint main(void) {\n    int m;\n    if (scanf(\"%d\", &m) != 1) return 0;\n    char **toks = malloc(sizeof(char*) * m);\n    for (int i = 0; i < m; i++) { toks[i] = malloc(16); scanf(\"%15s\", toks[i]); }\n    L = malloc(sizeof(int) * m); R = malloc(sizeof(int) * m); V = malloc(sizeof(long long) * m);\n    V[0] = atoll(toks[0]); L[0] = -1; R[0] = -1; int cnt = 1;\n    int *q = malloc(sizeof(int) * (m + 1)); int qh = 0, qt = 0; q[qt++] = 0; int i = 1;\n    while (qh < qt && i < m) {\n        int cur = q[qh++];\n        if (i < m && strcmp(toks[i], \"null\") != 0) { V[cnt] = atoll(toks[i]); L[cnt] = -1; R[cnt] = -1; L[cur] = cnt; q[qt++] = cnt; cnt++; }\n        i++;\n        if (i < m && strcmp(toks[i], \"null\") != 0) { V[cnt] = atoll(toks[i]); L[cnt] = -1; R[cnt] = -1; R[cur] = cnt; q[qt++] = cnt; cnt++; }\n        i++;\n    }\n    if (!leaf(0)) res[rn++] = V[0];\n    int cur = L[0];\n    while (cur != -1) {\n        if (!leaf(cur)) res[rn++] = V[cur];\n        cur = L[cur] != -1 ? L[cur] : R[cur];\n    }\n    addLeaves(0);\n    long long stack[5001]; int sn = 0;\n    cur = R[0];\n    while (cur != -1) {\n        if (!leaf(cur)) stack[sn++] = V[cur];\n        cur = R[cur] != -1 ? R[cur] : L[cur];\n    }\n    for (int k = sn - 1; k >= 0; k--) res[rn++] = stack[k];\n    for (int k = 0; k < rn; k++) printf(\"%lld%s\", res[k], k + 1 < rn ? \" \" : \"\\n\");\n    return 0;\n}\n","cpp":"#include <iostream>\n#include <vector>\n#include <string>\n#include <sstream>\nusing namespace std;\nvector<int> L, R;\nvector<long long> V, res;\nbool leaf(int x) { return L[x] == -1 && R[x] == -1; }\nvoid addLeaves(int x) {\n    if (leaf(x)) { res.push_back(V[x]); return; }\n    if (L[x] != -1) addLeaves(L[x]);\n    if (R[x] != -1) addLeaves(R[x]);\n}\nint main() {\n    ios::sync_with_stdio(false); cin.tie(nullptr);\n    int m; cin >> m; cin.ignore();\n    string line; getline(cin, line);\n    vector<string> toks;\n    { istringstream iss(line); string tk; while (iss >> tk) toks.push_back(tk); }\n    V.push_back(stoll(toks[0])); L.push_back(-1); R.push_back(-1); int cnt = 1;\n    vector<int> q{0}; size_t qh = 0, i = 1;\n    while (qh < q.size() && i < toks.size()) {\n        int cur = q[qh++];\n        if (i < toks.size() && toks[i] != \"null\") { V.push_back(stoll(toks[i])); L.push_back(-1); R.push_back(-1); L[cur] = cnt; q.push_back(cnt); cnt++; }\n        i++;\n        if (i < toks.size() && toks[i] != \"null\") { V.push_back(stoll(toks[i])); L.push_back(-1); R.push_back(-1); R[cur] = cnt; q.push_back(cnt); cnt++; }\n        i++;\n    }\n    if (!leaf(0)) res.push_back(V[0]);\n    int cur = L[0];\n    while (cur != -1) {\n        if (!leaf(cur)) res.push_back(V[cur]);\n        cur = L[cur] != -1 ? L[cur] : R[cur];\n    }\n    addLeaves(0);\n    vector<long long> stk;\n    cur = R[0];\n    while (cur != -1) {\n        if (!leaf(cur)) stk.push_back(V[cur]);\n        cur = R[cur] != -1 ? R[cur] : L[cur];\n    }\n    for (int k = (int)stk.size() - 1; k >= 0; k--) res.push_back(stk[k]);\n    for (size_t k = 0; k < res.size(); k++) { if (k) cout << ' '; cout << res[k]; }\n    cout << \"\\n\";\n    return 0;\n}\n","javascript":"const lines = require('fs').readFileSync(0, 'utf8').split('\\n');\nconst m = Number(lines[0]);\nconst toks = lines[1].trim().split(/\\s+/);\nconst V = [Number(toks[0])], L = [-1], R = [-1];\nlet cnt = 1;\nconst q = [0]; let qh = 0, i = 1;\nwhile (qh < q.length && i < toks.length) {\n    const cur = q[qh++];\n    if (i < toks.length && toks[i] !== 'null') { V.push(Number(toks[i])); L.push(-1); R.push(-1); L[cur] = cnt; q.push(cnt); cnt++; }\n    i++;\n    if (i < toks.length && toks[i] !== 'null') { V.push(Number(toks[i])); L.push(-1); R.push(-1); R[cur] = cnt; q.push(cnt); cnt++; }\n    i++;\n}\nconst leaf = (x) => L[x] === -1 && R[x] === -1;\nconst res = [];\nif (!leaf(0)) res.push(V[0]);\nlet cur = L[0];\nwhile (cur !== -1) {\n    if (!leaf(cur)) res.push(V[cur]);\n    cur = L[cur] !== -1 ? L[cur] : R[cur];\n}\nfunction addLeaves(x) {\n    if (leaf(x)) { res.push(V[x]); return; }\n    if (L[x] !== -1) addLeaves(L[x]);\n    if (R[x] !== -1) addLeaves(R[x]);\n}\naddLeaves(0);\nconst stk = [];\ncur = R[0];\nwhile (cur !== -1) {\n    if (!leaf(cur)) stk.push(V[cur]);\n    cur = R[cur] !== -1 ? R[cur] : L[cur];\n}\nfor (let k = stk.length - 1; k >= 0; k--) res.push(stk[k]);\nconsole.log(res.join(' '));\n"}$px$::jsonb,
