  $px${"java":"import java.util.*;\nimport java.io.*;\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        int m = Integer.parseInt(br.readLine().trim());\n        String[] toks = br.readLine().trim().split(\"\\\\s+\");\n        int sz = Math.max(1, m);\n        int[] L = new int[sz], R = new int[sz]; long[] V = new long[sz];\n        V[0] = Long.parseLong(toks[0]); L[0] = -1; R[0] = -1; int cnt = 1;\n        int[] q = new int[m + 1]; int qh = 0, qt = 0; q[qt++] = 0; int i = 1;\n        while (qh < qt && i < toks.length) {\n            int cur = q[qh++];\n            if (i < toks.length && !toks[i].equals(\"null\")) { V[cnt] = Long.parseLong(toks[i]); L[cnt] = -1; R[cnt] = -1; L[cur] = cnt; q[qt++] = cnt; cnt++; }\n            i++;\n            if (i < toks.length && !toks[i].equals(\"null\")) { V[cnt] = Long.parseLong(toks[i]); L[cnt] = -1; R[cnt] = -1; R[cur] = cnt; q[qt++] = cnt; cnt++; }\n            i++;\n        }\n        TreeMap<Integer, List<Long>> cols = new TreeMap<>();\n        ArrayDeque<int[]> dq = new ArrayDeque<>();\n        dq.add(new int[]{0, 0});\n        while (!dq.isEmpty()) {\n            int[] e = dq.poll();\n            cols.computeIfAbsent(e[1], z -> new ArrayList<>()).add(V[e[0]]);\n            if (L[e[0]] != -1) dq.add(new int[]{L[e[0]], e[1] - 1});\n            if (R[e[0]] != -1) dq.add(new int[]{R[e[0]], e[1] + 1});\n        }\n        StringBuilder sb = new StringBuilder();\n        for (List<Long> col : cols.values()) {\n            for (int k = 0; k < col.size(); k++) { if (k > 0) sb.append(' '); sb.append(col.get(k)); }\n            sb.append('\\n');\n        }\n        System.out.print(sb);\n    }\n}\n","python":"import sys\nfrom collections import deque, defaultdict\nlines = sys.stdin.read().split('\\n')\nm = int(lines[0])\ntoks = lines[1].split()\nV, L, R = [], [], []\nV.append(int(toks[0])); L.append(-1); R.append(-1)\nq = [0]; qh = 0; i = 1; cnt = 1\nwhile qh < len(q) and i < len(toks):\n    cur = q[qh]; qh += 1\n    if i < len(toks) and toks[i] != 'null':\n        V.append(int(toks[i])); L.append(-1); R.append(-1); L[cur] = cnt; q.append(cnt); cnt += 1\n    i += 1\n    if i < len(toks) and toks[i] != 'null':\n        V.append(int(toks[i])); L.append(-1); R.append(-1); R[cur] = cnt; q.append(cnt); cnt += 1\n    i += 1\ncols = defaultdict(list)\ndq = deque([(0, 0)])\nwhile dq:\n    x, c = dq.popleft()\n    cols[c].append(V[x])\n    if L[x] != -1:\n        dq.append((L[x], c - 1))\n    if R[x] != -1:\n        dq.append((R[x], c + 1))\nout = []\nfor c in sorted(cols):\n    out.append(' '.join(map(str, cols[c])))\nprint('\\n'.join(out))\n","c":"#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\nint main(void) {\n    int m;\n    if (scanf(\"%d\", &m) != 1) return 0;\n    char **toks = malloc(sizeof(char*) * m);\n    for (int i = 0; i < m; i++) { toks[i] = malloc(16); scanf(\"%15s\", toks[i]); }\n    int *L = malloc(sizeof(int) * m), *R = malloc(sizeof(int) * m);\n    long long *V = malloc(sizeof(long long) * m);\n    V[0] = atoll(toks[0]); L[0] = -1; R[0] = -1; int cnt = 1;\n    int *q = malloc(sizeof(int) * (m + 1)); int qh = 0, qt = 0; q[qt++] = 0; int i = 1;\n    while (qh < qt && i < m) {\n        int cur = q[qh++];\n        if (i < m && strcmp(toks[i], \"null\") != 0) { V[cnt] = atoll(toks[i]); L[cnt] = -1; R[cnt] = -1; L[cur] = cnt; q[qt++] = cnt; cnt++; }\n        i++;\n        if (i < m && strcmp(toks[i], \"null\") != 0) { V[cnt] = atoll(toks[i]); L[cnt] = -1; R[cnt] = -1; R[cur] = cnt; q[qt++] = cnt; cnt++; }\n        i++;\n    }\n    int *bnode = malloc(sizeof(int) * cnt);\n    int *bcol = malloc(sizeof(int) * cnt);\n    int bh = 0, bt = 0;\n    bnode[bt] = 0; bcol[bt] = 0; bt++;\n    long long *outv = malloc(sizeof(long long) * cnt);\n    int *outc = malloc(sizeof(int) * cnt);\n    int on = 0;\n    while (bh < bt) {\n        int x = bnode[bh]; int c = bcol[bh]; bh++;\n        outv[on] = V[x]; outc[on] = c; on++;\n        if (L[x] != -1) { bnode[bt] = L[x]; bcol[bt] = c - 1; bt++; }\n        if (R[x] != -1) { bnode[bt] = R[x]; bcol[bt] = c + 1; bt++; }\n    }\n    int minc = outc[0], maxc = outc[0];\n    for (int k = 0; k < on; k++) { if (outc[k] < minc) minc = outc[k]; if (outc[k] > maxc) maxc = outc[k]; }\n    for (int c = minc; c <= maxc; c++) {\n        int first = 1;\n        for (int k = 0; k < on; k++) if (outc[k] == c) { if (!first) putchar(' '); printf(\"%lld\", outv[k]); first = 0; }\n        putchar('\\n');\n    }\n    return 0;\n}\n","cpp":"#include <iostream>\n#include <vector>\n#include <string>\n#include <sstream>\n#include <map>\n#include <deque>\nusing namespace std;\nint main() {\n    ios::sync_with_stdio(false); cin.tie(nullptr);\n    int m; cin >> m; cin.ignore();\n    string line; getline(cin, line);\n    vector<string> toks;\n    { istringstream iss(line); string tk; while (iss >> tk) toks.push_back(tk); }\n    vector<int> L, R; vector<long long> V;\n    V.push_back(stoll(toks[0])); L.push_back(-1); R.push_back(-1); int cnt = 1;\n    vector<int> q{0}; size_t qh = 0, i = 1;\n    while (qh < q.size() && i < toks.size()) {\n        int cur = q[qh++];\n        if (i < toks.size() && toks[i] != \"null\") { V.push_back(stoll(toks[i])); L.push_back(-1); R.push_back(-1); L[cur] = cnt; q.push_back(cnt); cnt++; }\n        i++;\n        if (i < toks.size() && toks[i] != \"null\") { V.push_back(stoll(toks[i])); L.push_back(-1); R.push_back(-1); R[cur] = cnt; q.push_back(cnt); cnt++; }\n        i++;\n    }\n    map<int, vector<long long>> cols;\n    deque<pair<int,int>> dq;\n    dq.push_back({0, 0});\n    while (!dq.empty()) {\n        auto [x, c] = dq.front(); dq.pop_front();\n        cols[c].push_back(V[x]);\n        if (L[x] != -1) dq.push_back({L[x], c - 1});\n        if (R[x] != -1) dq.push_back({R[x], c + 1});\n    }\n    for (auto &kv : cols) {\n        for (size_t k = 0; k < kv.second.size(); k++) { if (k) cout << ' '; cout << kv.second[k]; }\n        cout << '\\n';\n    }\n    return 0;\n}\n","javascript":"const lines = require('fs').readFileSync(0, 'utf8').split('\\n');\nconst m = Number(lines[0]);\nconst toks = lines[1].trim().split(/\\s+/);\nconst V = [Number(toks[0])], L = [-1], R = [-1];\nlet cnt = 1;\nconst q = [0]; let qh = 0, i = 1;\nwhile (qh < q.length && i < toks.length) {\n    const cur = q[qh++];\n    if (i < toks.length && toks[i] !== 'null') { V.push(Number(toks[i])); L.push(-1); R.push(-1); L[cur] = cnt; q.push(cnt); cnt++; }\n    i++;\n    if (i < toks.length && toks[i] !== 'null') { V.push(Number(toks[i])); L.push(-1); R.push(-1); R[cur] = cnt; q.push(cnt); cnt++; }\n    i++;\n}\nconst cols = new Map();\nconst dq = [[0, 0]]; let dh = 0;\nwhile (dh < dq.length) {\n    const [x, c] = dq[dh++];\n    if (!cols.has(c)) cols.set(c, []);\n    cols.get(c).push(V[x]);\n    if (L[x] !== -1) dq.push([L[x], c - 1]);\n    if (R[x] !== -1) dq.push([R[x], c + 1]);\n}\nconst keys = [...cols.keys()].sort((a, b) => a - b);\nconsole.log(keys.map((c) => cols.get(c).join(' ')).join('\\n'));\n"}$px$::jsonb,
