-- ===========================================================================
-- 3. VALIDATION  (raises, never silently passes)
-- ===========================================================================
do $val$
declare
  v_cat_id text := 'dt-practice-binary-tree';
  v_n int;
begin
  if not exists (select 1 from public.dsa_topics where id = v_cat_id and kind = 'practice') then
    raise exception '0081/053: category % missing', v_cat_id;
  end if;
  select count(*) into v_n from public.dsa_problems
   where topic_id = v_cat_id and learning_topic_id is null and coalesce(status,'published') = 'published';
  if v_n < 15 then
    raise exception '0081/053: expected >= 15 Binary Tree practice problems, found %', v_n;
  end if;
  raise notice '0081/053 OK: % Binary Tree practice problems present.', v_n;
end
$val$;

notify pgrst, 'reload schema';
